    "descripcion": "Dentro de los 30 días hábiles después de iniciadas las clases, se puede solicitar, al Decanato, retiro y reserva de matricula. El estudiante de currículo\nflexible puede solicitar el retiro y la reserva de matrícula en alguno o todos los cursos que se hubieran matriculado. El estudiante de currículo rígido\nsolo podrá solicitar retiro y reserva del año académico en el que esta matriculado. El Decanato Oficializa el retiro y reserva mediante Resolución que\nentra en vigencia previa entrega del carné universitario.",
    "requisitos": "1.- Solicitud dirigida al Decano dentro de los 30 días hábiles después de iniciadas las clases (FUT).\n2.- Entrega de Carné Universitario.\n3.- Tener matrícula vigente a partir del segundo ciclo o segundo año.\n4.- No haber reservado o retirado matrícula en dos períodos continuos o tres no continuos.\n5.- Pago único por derecho de retiro o reserva.\nNotas:\n1.- Se puede solicitar retiro y reserva de matrícula por un máximo de dos (2) periodos lectivos continuos o tres (3) no continuos.\n2.- Los alumnos del primer año o del primer ciclo, no pueden solicitar retiro y reserva de matrícula.",
