    "requisitos": "1.- Solicitud dirigida al Rector (FUT)\n2.- Dos fotos a color, en fondo blanco, reciente, tamaño pasaporte. (caballeros: con saco, camisa y corbata; damas con traje de vestir).\n3.- Recibo de pago por Derecho de Duplicado de Grado o Título.\n4.- Adicionalmente deberá adjuntar:\n5.- A.- EN CASO DE PÉRDIDA\nDeclaración Jurada Simple de haber perdido el diploma. (en caso de robo o pérdida por causa natural).\nPresentación de la hoja completa en original de la publicación en el Diario de mayor circulación de la ciudad; del aviso de pérdida del diploma y\nde la solicitud del duplicado.\n6.- B.- EN CASO DE DETERIORO\nAdjuntar Diploma deteriorado y/o mutilado\nNotas:\n1.- En ambos casos una vez emitida la Resolución Rectoral que aprueba otorgar el duplicado, se le entregará al interesado un resumen de la misma\ny deberá publicarla en el Diario Oficial El Peruano y acreditará esta publicación ante la Oficina de Secretaría General, en un plazo que no exceda los\n30 días calendarios.\n2.- El duplicado se atenderá por una sola vez, debiendo el área de Registro de Grados y Títulos de Secretaría General llevar el registro\ncorrespondiente.",
    "formularios": "Formulario PDF: Formato Único de Trámite F-001\nUbicación: http://sut.pcm.gob.pe/sutArchivos/file_52_20210714_020643.pdf",
