    "titulo": "REGISTRO EN EL PADRÓN DE BENEFICIARIOS DE AUSPICIOS",
    "descripcion": "Aquellas entidades que deseen ser beneficiadas con el auspicio por parte de la UNT deberán previamente inscribirse en un padrón de entidades\nbeneficiarias de auspicio, cumpliendo con los requisitos establecidos.",
    "requisitos": "1.- Solicitud dirigida al Rector (FUT)\n2.- RUC activo\n3.- Copia legalizada o autenticada de la Escritura Pública de constitución como persona jurídica, acreditando una antigüedad no menor a TRES (03)\naños.\n4.- Copia de la vigencia de poder del representante legal de la institución, con una antigüedad no menor a 30 días.\n5.- Certificado domiciliario.\n6.- Documentación que acredite que los últimos tres años ha realizado actividades de capacitación.\n7.- Declaración jurada con firma legalizada, del representante legal de la solicitante, declarando no haber sido objetode sanción o no estar incurso en\nproceso de cualquier naturaleza por incumplimiento de obligaciones propias de las actividades de capacitación y que su representada tampoco lo\nestá.\n8.- Recibo por derecho de trámite de inscripción al padrón, en:\nINTERBANK Código de Servicio : 005-166-15 (Servicio AUSPICIOS)                       INTERBANK: Cta Cte. en Soles Nº 6163001972909 CCI:\n00361600300197290901\nNotas:\n1.- La sola inscripción no da derecho al auspicio de ninguna actividad académica",
