    "id": 47,
    "codigo": "PA5200CD83",
    "tipo": "Procedimiento Administrativo",
    "categoria": "Trámites Administrativos Generales",
    "titulo": "OTORGAMIENTO DE AUSPICIO",
    "descripcion": "Procedimiento por el cual las entidades inscritas en el padron de beneficiarios de auspicio pueden solicitar el auspicio para una actividad\ndeterminada.",
    "requisitos": "1.- Solicitud dirigida al Rector (FUT)\n2.- Recibo por derecho de trámite de auspicio, pagado\nen INTERBANK , Cuenta Corriente Nº 6163001972909 CCI 003-61600300197290901 - Servicio:Auspicios UNT.\n3.- Constancia de estar inscrito en el registro de entidades habilitadas para auspicio de la UNT.\n4.- Plan o programa de la actividad a ser auspiciada, debidamente descrita, fundamentada, contextualizada, organizada, cronogramada y\npresupuestada (indicar el monto preciso a cobrar por los asistentes).\n5.- Modelo de certificado expedirse y firmarse.\n6.- Hoja de vida de los capacitadores o ponentes, en el caso de las actividades académicas o de los artistas u otros en el caso de ser actividades no\nacadémicas.\n7.- Carta compromiso de pago de los derechos establecidos en el artículo 14° del Reglamento General para el Otorgamiento de Auspicios en la UNT.\nNotas:\n1.- La institución abonará a la UNT el 30% del monto total recaudado; si dicho auspicio involucra el uso de los ambientes universitarios el monto\nserá de 35% del monto ya referido, así como también el importe de una garantía del 20% del total estimado del presupuesto del proyecto de la\nactividad, en previsión de daños en la infraestructura o deterioro o pérdida de equipos. La entidad está obligada a efectuar el pago de la garantía y el\n50% del total estimado hasta un día antes de realizada la actividad.\nSi las actividades son realizadas por estudiantes a través de sus institutos, asociaciones o centros Federados, además de docentes, administrativos\no cualquier otro gremio debidamente reconocido y que pertenezcan a la UNT, se abonara el 5% de lo recaudado, monto que involucra previa\ncoordinación y disponibilidad, el uso de los ambientes universitarios.\nPara eventos artísticos o culturales, el auspiciado abonará el 10% del monto recaudado; si dicho auspicio involucra el uso de ambientes el monto\nabonado será del 15%.\nDicho artículo no es aplicable para el evento realizado por la misma UNT, y que tenga un fin de proyección social, o cuando se trate de actividades\nrealizadas por instituciones registradas como beneficiarias de auspicio y que tengan también un fin no lucrativo, lo que deberá ser debidamente\nprobado al momento de solicitar el auspicio respectivo.",
    "formularios": "Formulario PDF: F-001 Formato Único de Trámite\nUbicación: http://sut.pcm.gob.pe/sutArchivos/file_52_20210621_132650.pdf",
    "canales": "Atención Presencial: Mesa de Partes de Secretaría General.",
    "pago": "Recibo por derecho de trámite solicitando otorgamiento de auspicio\nMonto - S/ 8.00",
    "modalidad": "Otras opciones\nAgencia Bancaria:\nINTERBANK Código de Servicio : 005-166-15   INTERBANK: Cta\nCte. en Soles Nº 6163001972909 CCI: 00361600300197290901",
    "costoCorto": "S/ 8.00",
    "plazo": "30 días hábiles",
    "plazoCorto": "30 días hábiles",
