    "descripcion": "Queja por defecto de tramitación: Es toda manifestación de disconformidad efectuada por el usuario, sobre defectos de tramitación de sus peticiones\npresentadas, las cuales se encuentran reguladas por el artículo 158° de la Ley 27444.\nLa queja por defecto de tramitación es un remedio procesal, por lo tanto no posee la naturaleza de recurso administrativo.",
