    "requisitos": "1.- Recurso firmado por el recurrente y un letrado, conteniendo:\nIdentificación del impugnante, debiendo consignar su nombre y número de documento oficial de identidad, o su denominación o razón social. En\ncaso de actuación mediante representante, se acompañará la documentación que acredite tal representación.\nSeñalar como domicilio procesal una dirección electrónica propia.\nEl petitorio, de manera clara y concreta indicar lo que se solicita.\nLos fundamentos de hecho y derecho que sustentan su petitorio.\nLas pruebas instrumentales pertinentes.\nLa garantía por interposición del recurso de apelación\n2.- La apelación contra el otorgamiento de la buena pro o contra los actos dictados con anterioridad a ella debe interponerse dentro de los ocho (8)\ndías hábiles siguientes de haberse notificado el otorgamiento de la buena pro. En el caso de Adjudicaciones Simplificadas, Selección de Consultores\nIndividuales y Comparación de Precios, la apelación se presenta dentro de los cinco (5) días hábiles siguientes de haberse notificado el otorgamiento\nde la buena pro. En el caso de Subasta Inversa Electrónica, el plazo para la interposición del recurso es de cinco (5) días hábiles, salvo que su valor\nreferencial corresponda al de una licitación pública o concurso público, en cuyo caso el plazo es de ocho (8) días hábiles..\n3.- Pago",
