    "requisitos": "1.- Solicitud dirigida al Decano de la Facultad donde desea ser incorporado.\n2.- Ser docente universitario cesante o jubilado, con mínimo 30 años los varones y 25 años las mujeres de servicios docentes prestados a la\nUniversidad; habiendo dedicado sus últimos 10 años de actividad académica a la UNT en forma ininterrumpida.\n3.- Certificado de antecedentes académicos que acredita que no estuvo afectado por medida disciplinaria alguna, expedido por la Oficina General de\nPersonal y visado por el Decano donde acumuló su mayor tiempo docente\n4.- Cuatro ejemplares del proyecto de trabajo.\n5.- Adjuntar elementos de evaluación de alta calidad académica según lo establece el anexo 01 del Reglamento, aprobado con R.R. N° 1320-94\nNotas:\n1.- En caso la candidatura sea solicitada por un organismo universitario deberá presentar los requisitos 2, 3, 4, 5 y adicionalmente:\n* El Acta de acuerdo donde se solicita el nombramiento.\n* La aceptación escrita del profesor candidato.",
