    "titulo": "INSCRIPCION AL CONCURSO DE PROMOCION DOCENTE",
    "descripcion": "Los postulantes que deseen participar podrán inscribirse al concurso de promoción docente si cumplen los requisitos establecidos",
    "requisitos": "1.- Solicitud dirigida al Rector de la UNT, debidamente firmada.\n2.- Copia escaneada de recibo por concepto de derecho de inscripción.\n3.- Copia de DNI\n4.- Copia de Grados Académicos de Bachiller, Maestro y/o Doctor, en el caso de graduados en Universidades extranjeras, el grado deberá ser\nvisado por el Ministerio de Relaciones Exteriores y reconocido por SUNEDU y/o revalidado por una Universidad Peruana autorizada.\n5.- Copia de Título Profesional expedido por una Universidad Peruana (copia autenticada por el Secretario General de la Universidad de\nprocedencia). Los profesionales titulados en el extranjero presentarán el Título revalidado por una Universidad Peruana, autorizada por SUNEDU.\n6.- Certificado y/o constancia de habilitación del Colegio Profesional correspondiente.\n7.- Constancia de no tener sanción administrativa disciplinaria, con Resolución del Tribunal de Honor u organismo similar y/o resolución confirmada\npor el Consejo Universitario, salvo rehabilitación administrativa expedida de conformidad con las normas vigentes.\n8.- Certificado de buena salud, expedido por un centro hospitalario del Ministerio de Salud o ESSALUD y/o en su defecto declaración jurada de gozar\nde buena salud.\n9.- Certificado de salud mental, expedido por un centro hospitalario del Ministerio de Salud o ESSALUD o por un profesional de la especialidad y/o\ndeclaración jurada de buena salud mental.\n10.- Declaración jurada con firma legalizada por Notario Público, de no tener antecedentes penales por la comisión de delito doloso. (Formato B).\n11.- Declaración jurada de no tener relación conyugal o de consanguinidad en línea directa o colateral, hasta el cuarto grado, o afinidad hasta el\nsegundo grado, con alguno de los miembros del Jurado o sus cónyuges.\n12.- Declaración jurada de no estar incurso en incompatibilidad laboral. (Formato B).\n13.- Un (01) ejemplar del trabajo de habilitación con su respectiva guía de aprendizaje, relacionado con las disciplinas que cultiva el Departamento\nAcadémico del docente hábil, se presentarán en archivo digital PDF, a través del correo institucional del Área de Personal Académico\nconcursopromociondocente2020@unitru.edu.pe",
