    "descripcion": "La Unidad de Recursos Humanos remitirá las solicitudes a la ONP.",
    "requisitos": "1.- Solicitud del Cónyuge sobreviviente o su representante legal, con indicación expresa de lo requerido dirigida al Señor Rector, (FUT) indicando su\ndirección domiciliaria.\n2.- Copia vigente y legible del DNI del solicitante.\n3.- Partida de Matrimonio Civil, emitida con posterioridad a la fecha de fallecimiento del causante, con una antigüedad no mayor de tres meses.\n4.- Partida de Defunción del causante, con una antigüedad no mayor a tres meses.\n5.- Declaración Jurada de acuerdo al Anexo VIII de la R.J. N° 125-2008-JEFATURA/ONP, publicada el 10.07.2008.\nNotas:\n1.- En caso de ser hombre el solicitante presentará además:\n* Declaración Jurada de incapacidad de subsistir por si mismo, carecer de renta afecta en montos superiores a la pensión y no estar amparado por\nalgún sistema de seguridad social. (Anexo VIII de la R.J. N° 125-2008-JEFATURA/ONP, publicada el 10.07.2008)\n2.- En los casos en que el Matrimonio haya sido realizado antes del año de fallecimiento del causante presentará adicionalmente:\n* Copia certificada del parte policial y/o certificado de necropsia si el fallecimiento fue por accidente.\n* Copia certificada de la partida de nacimiento de hijos en común, con una antigüedad no mayor a tres meses.\n* Certificado médico que acredite el estado de gravidez de la cónyuge a la fecha de fallecimiento del causante.\n* Si el cónyuge sobreviviente fuese minusválido, adjuntar Dictamen de comisión médica del Seguro Social de Salud (EsSalud) o del Ministerio de\nSalud que acredite la minusvalía.",
