    "titulo": "ENVÍO A LA ONP DE SOLICITUDES Y DOCUMENTOS DEL RÉGIMEN DE PENSIONES DEL DECRETO LEY N° 20530 c) Para el caso de pensión de Sobrevivientes-Orfandad",
    "descripcion": "La Unidad de Recursos Humanos remitirá las solicitudes a la ONP.",
    "requisitos": "1.- Solicitud (FUT) del recurrente o su representante legal, dirigida al Señor Rector, requiriendo Pensión de Orfandad indicando la dirección\ndomiciliaria.\n2.- Copia vigente y legible del DNI del solicitante.\n3.- Partida de Nacimiento de hijos del causante que solicitan pensión, con una antigüedad no mayor a tres meses\n4.- Partida de Defunción del causante, con una antigüedad no mayor de tres meses.\n5.- Declaración Jurada de acuerdo al Anexo VIII de la R.J. N° 125-2008-JEFATURA/ONP, publicada el 10.07.2008.\nNotas:\n1.- EN CASO DE HIJOS ADOPTIVOS:\n* Resolución que declare haberse realizado la adopción por el causante.\n* Partida de Nacimiento con la anotación correspondiente, con un máximo de tres meses de antigüedad.\n2.- EN CASO DE HIJO INCAPACITADO:\n* Copia legible y vigente del DNI del beneficiario.\n* Certificado Médico expedido por una Comisión Médica del Ministerio de Salud o del Seguro Social de Salud, en la que se declare la incapacidad\nabsoluta para el trabajo del beneficiario.\n* Resoluciones Judiciales de nombramiento del curador, de ser el caso.\n* Documento de identidad del curador, de ser el caso.\n3.- CASO DE HIJO CON ESTUDIOS DE NIVEL BASICO O SUPERIOR :\n* Copia legible y vigente del DNI del beneficiario.\n* Certificado de Estudios (para continuar con Pensión de hijo mayor de edad).",
