    "descripcion": "Los estudiantes de la UNT pueden solicitar su inscripción bajo esta modalidad hasta el VIII ciclo.",
    "requisitos": "1.- Solicitud de inscripción (formato vía web)\n2.- Recibo de pago por derecho de inscripción.\n3.- Constancia de ingreso expedida por la Dirección de Admisión de la UNT\n4.- Certificado original de estudios universitarios.\n5.- Sílabos de los cursos aprobados, visados por la autoridad competente.\n6.- Constancia de matrícula del semestre o año académico vigente.\n7.- Documento de Identidad (DNI) vigente, o pasaporte.\nNotas:\n1.- El estudiante de la UNT, hasta el VIII ciclo, puede solicitar Traslado Interno a cualquier carrera profesional, dentro del Grupo de carreras y del\nCuadro de Vacantes aprobadas; siempre y cuando no haya sido separado de la carrera por motivos académicos o disciplinarios y acredite haber\naprobado un mínimo de cuatro ciclos, dos años académicos, o 72 créditos.\n2.- El estudiante podrá inscribirse como postulante al concurso de admisión por traslado interno hasta el VIII ciclo.\n3.- En caso de ingreso por traslado el estudiante debe iniciar su proceso de convalidación de asignaturas en la Escuela Académica Profesional\nrespectiva.",
