    "titulo": "INSCRIPCIÓN AL CONCURSO DE ADMISIÓN PARA SEGUNDA PROFESIÓN",
    "descripcion": "Puede postular a seguir estudios de Segunda Profesión en la UNT aquel profesional que ha obtenido título en alguna universidad del país reconocida\npor la SUNEDU, o en el extranjero, debidamente revalidado por las instituciones universitarias autorizadas por la SUNEDU, o en alguna de las\nInstituciones con rango universitario consideradas en la Ley Universitaria.",
    "requisitos": "1.- Solicitud de inscripción (formato vía web).\n2.- Recibo de pago por derecho de inscripción.\n3.- Copia del título profesional autenticada por el profesor Secretario General de la Universidad de origen.\n4.- Certificado original de estudios universitarios.\n5.- Documento de Identidad (DNI) vigente, pasaporte o carné de extranjería\n6.- Si el postulante no es hispano hablante deberá acreditar manejo del idioma español. Si la documentación no está en idioma español, deberá\npresentar una traducción oficial, completa, de los mismos, emitida por el Departamento de Idiomas y Lingüística, o del Centro de Idiomas de la UNT,\no del Centro de Idiomas de la Escuela de Postgrado de la UNT.",
    "formularios": "",
    "canales": "Atención Presencial: Mesa de Partes de la Dirección de Admisión - Ciudad Universitaria. Av .Juan Pablo II s/n - 3ra. Puerta\nAtención Virtual: Página web Dirección de Admisión:       http://www.admisionunt.info/",
    "pago": "Modalidad de pago\nRecibo de pago por derecho de inscripción: Admisión Segunda Profesión\nMonto - S/ 770.00",
