    "descripcion": "Los profesionales que cumplan los requisitos podrán inscribirse y postular a la 2da Especialidad en Estomatología.",
    "requisitos": "1.- Solicitud de postulación dirigida al Director de la Unidad de Segunda Especialidad de Estomatología.\n2.- Constancia original de registro y habilidad profesional expedida por el Colegio Odontológico del Perú.\n3.- Copia autenticada del titulo por la Secretaría General de la Universidad de origen o de la Universidad que revalidó el título o por la Asamblea\nNacional de Rectores.\n4.- Los odontólogos titulados en el extranjero, deberán presentar fotocopia legalizada por Notario Público del titulo de cirujano dentista revalidado en\nel país, por la Asamblea Nacional de Rectores ó Universidad autorizada.\n5.- En el caso de postulantes internacionales, deberán presentar fotocopia de su Título Profesional legalizado notarialmente, conteniendo las\nlegalizaciones consulares correspondientes. Así mismo presentarán la autorización para ejercicio temporal del Colegio Odontológico del Perú.\n6.- Certificado original de promedio promocional ponderado, excluyendo el internado, expedido por la Facultad de Odontología respectiva, en el que\ndebe constar además el orden de mérito y el número de egresados de la correspondiente promoción. (OPCIONAL).\n7.- Resolución original del Servicio Rural Urbano Marginal de Salud (SERUMS) a partir de diciembre de 1981, debiendo presentar la respectiva\nresolución de término a fin de ser declarado APTO, para la postulación en el Proceso de Admisión. Estos documentos deben ser expedidos por la\nDirección Regional de Salud correspondiente o por el Instituto de Desarrollo de Recursos Humanos (IDREH). Están exceptuados de este requisito\naquellos odontólogos extranjeros, debidamente acreditados, que postulen a la especialidad y que concluido su entrenamiento retornen a su país.\n(OPCIONAL).\n8.- Certificado médico original de salud física y certificado médico de salud mental, otorgados por los establecimientos del Sector Salud, Hospitales\nNivel III o IV, en los que se acredite su buen estado de salud, con una antigüedad de expedición no mayor de 3 meses.\n9.- Certificado de Antecedentes Penales, otorgado por el poder Judicial.\n10.- Constancia de suficiencia básica del Idioma inglés, que implica la capacidad del postulante de leer y comprender a nivel básico un texto.\n11.- Declaración Jurada de compromiso, con firma legalizada notarialmente (según formato anexo).\n12.- Dos (2) fotografías de frente a color fondo blanco (con vestimenta formal), tamaño carné.\n13.- Pago por derecho de postulación (S/ 500.00) y carpeta de postulante (S/ 200.00)",
