    "descripcion": "Los ingresantes en las diferentes modalidades deben solicitar su acreditación a la Dirección de Admisión lo cual les permite obtener su constancia de\ningresante, documento que posteriormente le permitirá realizar el proceso de matrícula.",
    "requisitos": "1.- Certificado de estudios original del 1º al 5º grado de educación secundaria o sus equivalentes, visado por la Instancia Educativa competente.\n2.- Presentar original del Documento de Identidad o pasaporte.\n3.- Pago por derecho de acreditación.\n4.- Los demás documentos exigidos por la modalidad:\na) En caso de Ingresante CEPUNT: Constancia de Ingreso emitida por CEPUNT\nb) En caso de Premios de Excelencia: Acta Original que Acredite el orden de mérito.\nNotas:\n1.- Resolución Directoral que acepta renuncia a la carrera que venía estudiando (ingresantes que ya son estudiantes de la UNT).\n2.- LOS POSTULANTES DE 5TO DE SECUNDARIA que obtuvieron una vacantes deberán acercarse a recoger su CONSTANCIA DE INGRESO -\n5TO AÑO, con su apoderado portando sus respectivos documentos de Identidad.\n3.- Los datos del ingresante consignados en los documentos originales: nombres y apellidos, grados de estudio, notas, nombres de las instituciones,\nfirmas de las autoridades que refrendan los documentos, sellos y las formalidades de los documentos, deben corresponderse y no presentar\nalteraciones de forma y/o fondo.",
